function summary=export_hcp_behavior_events(workspace)
%EXPORT_HCP_BEHAVIOR_EVENTS 事后校验响应窗口与EV时钟，复用已拟合潜变量，不重拟合。
if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function;base=fullfile(workspace,'derivatives','function_stage3_behavior_20261017');out=fullfile(base,'verified_event_exports');if isfolder(out),error('cog:Exists','Preserve successful event export');end;mkdir(out);preparation=jsondecode(fileread(fullfile(base,'PREPARATION.json')));summary=struct('records',{{}});
for k=1:numel(preparation.records)
    record=preparation.records(k);source=fileparts(record.source);raw=cog.read_tsv(record.source);trialFile=fullfile(base,string(record.subject)+"_"+string(record.run)+"_trials.tsv");tr=cog.read_tsv(trialFile);rows=str2double(erase(tr.trial_id,"eprime_row_"));sync=readmatrix(fullfile(source,'EVs','Sync.txt'),'FileType','text');window=str2double(raw.('ResponsePeriod.OnsetTime')(rows))/1000-sync(1);keypress=str2double(raw.('FilteredTrialStats.RTTIME')(rows))/1000-sync(1);published=[];
    for name={'response_story','response_math'},a=readmatrix(fullfile(source,'EVs',[name{1} '.txt']),'FileType','text');published=[published;a(:,1)];end %#ok<AGROW>
    difference=min(abs(window-published'),[],2);if any(~isfinite(window)|~isfinite(keypress)|keypress<0)||any(difference>=.02)||any(diff(keypress)<0),error('cog:ExampleTiming','Response-window clock could not be verified; do not guess a shift');end
    latentFile=fullfile(base,'rw_softmax',record.subject,"LANGUAGE_"+string(record.run),'trial_latents.tsv');latent=cog.read_tsv(latentFile);if ~isequal(latent.trial_id,tr.trial_id),error('cog:ExampleTrialIds','Frozen latent trial identities do not match prepared input');end
    choice=str2double(latent.choice);q=[str2double(latent.q_before_action_1) str2double(latent.q_before_action_2)];chosen=q(sub2ind(size(q),(1:height(latent))',choice));pe=str2double(latent.prediction_error);events=cog.parametric_events(keypress,zeros(size(keypress)),[chosen pe],{'q_before_choice','accuracy_proxy_prediction_error'},'engineering_choice',true);
    folder=fullfile(out,record.subject,"LANGUAGE_"+string(record.run));mkdir(folder);save(fullfile(folder,'multiple_conditions.mat'),'-struct','events');eventTable=table(latent.trial_id,keypress,zeros(size(keypress)),window,chosen,pe,'VariableNames',{'trial_id','onset_seconds','duration_seconds','response_window_onset_seconds','q_before_choice','accuracy_proxy_prediction_error'});writetable(eventTable,fullfile(folder,'parametric_events.tsv'),'FileType','text','Delimiter','\t');summary.records{end+1}=struct('subject',record.subject,'run',record.run,'nEvents',height(latent),'maxWindowClockErrorSeconds',max(difference),'inputLatents',latentFile);
end
summary.scope='Published response EV onsets are response-window starts, not keypresses; verify those window times against raw ResponsePeriod.OnsetTime and Sync, then retain raw keypress timing. Accuracy-proxy PE at keypress is an engineering convention, not a recorded reward-feedback event. Existing fits/preparation/validation files unchanged. SPM multiple-conditions contract exported, no GLM estimated.';cog.write_json(fullfile(out,'TIMING_POSTCHECK.json'),summary);
end
